CREATE TABLE IF NOT EXISTS cms_fields (page_slug VARCHAR(40) NOT NULL, field_key VARCHAR(80) NOT NULL, field_value TEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(page_slug,field_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_gallery (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(190) NOT NULL, caption VARCHAR(250) NOT NULL DEFAULT '', alt_text VARCHAR(250) NOT NULL DEFAULT '', is_visible TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
